const CAT_SERVICES = [['pickup', 'Pickup', false], ['delivery', 'Delivery', true]]; // root options for every client; address only for Delivery
const CAT_SVC_LABEL = { pickup: 'Pickup', delivery: 'Delivery', 'on-site': 'On-site' }; // 'on-site' kept for old rows only
const CAT_UNITS = { person: 'per person', tray: 'per tray', half_pan: 'per half pan', full_pan: 'per full pan', each: 'each' };
const cmS = (v, n) => String(v ?? '').trim().slice(0, n);
const cmPrice = v => { const n = Math.round(parseFloat(String(v ?? '').replace(/[$,\s]/g, '')) * 100) / 100; return Number.isFinite(n) && n >= 0 && n < 100000 ? n : null };
function cmCleanSize(z, i) { return { id: /^[a-z0-9]{3,16}$/.test(String(z.id || '')) ? z.id : 's' + Math.random().toString(36).slice(2, 9), label: cmS(z.label, 40), price: cmPrice(z.price), unit: CAT_UNITS[z.unit] ? z.unit : 'each', serves: Math.max(0, Math.min(1000, Math.floor(+z.serves || 0))), min_qty: Math.max(1, Math.min(1000, Math.floor(+z.min_qty || 1))) } }
// v64b (t708u): every catering item has 1-8 size options. Older single-price items are read as one size.
function cmCleanItem(i) { const sz = (Array.isArray(i.sizes) && i.sizes.length ? i.sizes : [{ label: '', price: i.price, unit: i.unit, serves: i.serves, min_qty: i.min_qty }]).slice(0, 8).map(cmCleanSize);
  return { id: /^[a-z0-9]{4,16}$/.test(String(i.id || '')) ? i.id : 'i' + Math.random().toString(36).slice(2, 10), src: /^k[a-z0-9]{4,16}$/.test(String(i.src || '')) ? i.src : '', name: cmS(i.name, 80) || 'Item', description: cmS(i.description, 400), sizes: sz, active: i.active !== false } }
function cmCleanSched(s) { s = s && typeof s === 'object' ? s : {}; const d = v => /^\d{4}-\d{2}-\d{2}$/.test(v || '') ? v : '', t = v => /^\d{2}:\d{2}$/.test(v || '') ? v : ''; return { from: d(s.from), to: d(s.to), days: [...new Set((Array.isArray(s.days) ? s.days : []).map(Number).filter(x => x >= 0 && x <= 6))].sort(), start: t(s.start), end: t(s.end) } }
function nowCT() { const p = Object.fromEntries(new Intl.DateTimeFormat('en-US', { timeZone: 'America/Chicago', weekday: 'short', hour: '2-digit', minute: '2-digit', hourCycle: 'h23' }).formatToParts(new Date()).map(x => [x.type, x.value])); return { date: todayCT(), dow: ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'].indexOf(p.weekday), hm: p.hour + ':' + p.minute } }
function cmActive(mn, now = nowCT()) {
  if (mn.on_mode === 'on') return true; if (mn.on_mode !== 'schedule') return false; const s = mn.sched || {};
  if (s.from && now.date < s.from) return false; if (s.to && now.date > s.to) return false;
  if (s.days && s.days.length && !s.days.includes(now.dow)) return false;
  if (s.start && now.hm < s.start) return false; if (s.end && now.hm >= s.end) return false; return true;
}
const cmRow = r => ({ ...r, sched: JSON.parse(r.sched || '{}'), items: JSON.parse(r.items || '[]') });
async function cmList(env, slug) { return (await env.DB.prepare('SELECT * FROM portal_catmenus WHERE client_slug=? ORDER BY sort,id').bind(slug).all()).results.map(cmRow) }
async function cmPublic(env, slug) { const now = nowCT(); return (await cmList(env, slug)).filter(m => cmActive(m, now)).map(m => ({ id: m.id, name: m.name, items: m.items.filter(i => i.active).map(cmCleanItem).map(i => ({ id: i.id, name: i.name, description: i.description, sizes: i.sizes.map(z => ({ ...z, unit_label: CAT_UNITS[z.unit] })) })) })).filter(m => m.items.length) }
// Public form schema (served in /api/forms/<biz>?module=catering as config.form). Sites render it with /embed/catering.js.
async function catFormSchema(env, slug) { return { services: CAT_SERVICES.map(([key, label, addr]) => ({ key, label, address: addr })), address_fields: [['address', 'Street address'], ['city', 'City'], ['zip', 'ZIP code']], guests_min: 10, guests_max: 1000, locations: (await env.DB.prepare('SELECT slug,name,address,status FROM portal_locations WHERE client_slug=? ORDER BY sort,name').bind(slug).all()).results.filter(l => l.status !== 'closed').map(l => ({ slug: l.slug, name: l.name, address: l.address || '', open: l.status === 'open' })), menus: await cmPublic(env, slug) } }
// Copy main-menu items ticked "Available for catering" (item.catering + item.cid) into the first catering menu. Copies are independent after that.
// v64b (t708u): unticking removes only the copies linked to that main item (src = cid). Catering-only items are never touched.
async function cmSyncFromMenu(env, slug, menu, who) {
  const want = [], off = new Set(); for (const c of menu.categories || []) for (const i of c.items || []) { if (!/^k[a-z0-9]{4,16}$/.test(i.cid || '')) continue; if (i.catering === true) want.push(i); else off.add(i.cid) }
  const menus = await cmList(env, slug), now = Date.now(); let removed = 0;
  for (const mn of menus) { const keep = mn.items.filter(x => !(x.src && off.has(x.src))); if (keep.length !== mn.items.length) { removed += mn.items.length - keep.length; mn.items = keep; await env.DB.prepare('UPDATE portal_catmenus SET items=?,updated_at=?,updated_by=? WHERE id=?').bind(JSON.stringify(keep), now, who, mn.id).run() } }
  const have = new Set(menus.flatMap(m => m.items.map(i => i.src)).filter(Boolean)), add = want.filter(i => !have.has(i.cid));
  if (!add.length) return { copied: 0, removed };
  let tgt = menus[0]; if (!tgt) { const id = (await env.DB.prepare("INSERT INTO portal_catmenus(client_slug,name,on_mode,sched,items,sort,created_at,updated_at,updated_by) VALUES(?,?,'off','{}','[]',0,?,?,?) RETURNING id").bind(slug, 'Catering menu', now, now, who).first()).id; tgt = { id, items: [] } }
  const items = tgt.items.concat(add.map(i => cmCleanItem({ src: i.cid, name: i.name, description: i.description, sizes: [{ label: '', price: i.price, unit: 'each', min_qty: 1 }], active: true })));
  await env.DB.prepare('UPDATE portal_catmenus SET items=?,updated_at=?,updated_by=? WHERE id=?').bind(JSON.stringify(items.slice(0, 300)), now, who, tgt.id).run(); return { copied: add.length, removed };
}
