    await socTables(env);
    const lo = Date.parse(dates[0] + 'T00:00:00Z') - 18 * 36e5, hi = Date.parse(dates[dates.length - 1] + 'T00:00:00Z') + 30 * 36e5;
    const rows = (await env.DB.prepare("SELECT network, at, text, media, link, interactions, reach FROM portal_social_posts WHERE client_slug=? AND at BETWEEN ? AND ? AND COALESCE(state,'') NOT IN ('removed','draft','superseded') AND COALESCE(example,0)=0 AND COALESCE(draft,0)=0").bind(slug, lo, hi).all()).results;
