      if ((await env.DB.prepare('SELECT COUNT(*) n FROM portal_passkeys WHERE email=?').bind(u.email).first()).n >= 10) return J({ error: 'You can have up to 10 passkeys.' }, 400);
      const name = String(b.name || '').trim().slice(0, 60) || 'Passkey';
