      await env.DB.prepare('INSERT INTO portal_passkeys(id,email,name,jwk,alg,sign_count,transports,created_at) VALUES(?,?,?,?,?,?,?,?)').bind(id, u.email, name, JSON.stringify(jwk), alg, a.count, JSON.stringify(tr), Date.now()).run();
      return J({ ok: true });
