    if (!admin) { const my = slugsOf(u), cq = url.searchParams.get('client'); if (cq && my.includes(cq)) { sql += ' AND t.client_slug=?'; a.push(cq) } else { sql += ` AND t.client_slug IN (${my.map(() => '?').join(',') || "''"})`; a.push(...my) } } else if (url.searchParams.get('client')) { sql += ' AND t.client_slug=?'; a.push(url.searchParams.get('client')) }
