    const subject = String(form.get('subject') || '').trim().slice(0, 140), desc = String(form.get('description') || '').trim().slice(0, 10000);
    const category = String(form.get('category') || ''), priority = String(form.get('priority') || 'normal');
    const fs_ = String(form.get('client_slug') || ''), slug = admin ? fs_ : slugsOf(u).includes(fs_) ? fs_ : u.client_slug;
