// Bare host.tld. Strips one leading @ or http(s):// and trailing dots or slashes. Blank means clear.
function normEmailDomain(raw) {
  if (typeof raw !== 'string') return { error: 'Enter just the domain, like catfishcove.co.' };
  if (!raw.trim()) return { clear: true };
  const s = raw.trim().toLowerCase().replace(/^@/, '').replace(/^https?:\/\//, '').replace(/[./]+$/, '');
  if (!s || !/^[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?(?:\.[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?)+$/.test(s))
    return { error: 'Enter just the domain, like catfishcove.co. Leave out https:// and anything after the name.' };
  return { domain: s };
}
function normEmailMailbox(raw) {
  if (raw == null || (typeof raw === 'string' && !raw.trim())) return { mailbox: 'reservations' };
  if (typeof raw !== 'string') return { error: 'The mailbox is the word before the @, like reservations.' };
  const s = raw.trim().toLowerCase();
  if (/[\s@]/.test(s) || s.length > 64) return { error: 'The mailbox is the word before the @, like reservations. Do not include spaces or an @.' };
  return { mailbox: s };
}
const emailFromOf = em => {
  if (!em || typeof em !== 'object' || Array.isArray(em) || !String(em.domain || '').trim()) return '(none)';
  return (String(em.mailbox || '').trim().toLowerCase() || 'reservations') + '@' + String(em.domain).trim().toLowerCase().replace(/^@/, '').replace(/\.+$/, '');
};
