  const brand = await resBrand(env, slug); if (!brand) return J({ error: 'Reservations are not turned on for this client.' }, 404);
  const row = await env.LEADS.prepare(`SELECT id,status,name,phone,email,res_date,res_time,party_size FROM ${RES_TABLE} WHERE id=? AND brand=? AND COALESCE(spam,0)=0`).bind(id, brand).first();
  if (!row) return J({ error: 'That reservation is not on this client’s list.' }, 404);
  const to = String(row.email || '').trim(); if (!to) return J({ error: 'This request has no email address, so there is nowhere to send it.' }, 400);
