    "var f=document.getElementById('f');f.addEventListener('submit',async function(ev){ev.preventDefault();msg('',1);var fd=new FormData(f),body={action:'update'};fd.forEach(function(v,k){body[k]=v});var time=body.res_time||'';if(/^\\d{2}:\\d{2}$/.test(time))body.res_time=time;else if(/^\\d{2}:\\d{2}:/.test(time))body.res_time=time.slice(0,5);" +
    "var btn=f.querySelector('button.primary');btn.disabled=true;try{var rr=await fetch('/api/public/reservation/'+encodeURIComponent(token),{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(body)});var jj=await rr.json();if(!rr.ok)throw new Error(jj.error||'Could not save');msg('Saved. You’re all set.',1);if(jj.reservation){x=jj.reservation}}catch(e){msg(e.message||'Could not save')}finally{btn.disabled=false}});" +
    "document.getElementById('cancel').onclick=async function(){if(!confirm('Cancel this reservation?'))return;msg('',1);try{var rr=await fetch('/api/public/reservation/'+encodeURIComponent(token),{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({action:'cancel'})});var jj=await rr.json();if(!rr.ok)throw new Error(jj.error||'Could not cancel');lead.textContent='Your reservation has been cancelled.';box.innerHTML='<p class=\"msg ok\">Cancelled. Thanks for letting us know.</p>'}catch(e){msg(e.message||'Could not cancel')}};" +
    "}catch(e){lead.textContent=e.message||'This manage link is invalid or has expired.';}})();</script></body></html>";
  return new Response(html, { headers: { 'content-type': 'text/html; charset=utf-8', 'cache-control': 'no-store', 'x-robots-tag': 'noindex' } });
