async function brevoKey(env, slug) { const r = await env.DB.prepare('SELECT key_sealed,list_id FROM portal_brevo WHERE client_slug=?').bind(slug).first(); if (!r) return null; try { return { key: new TextDecoder().decode(await unseal(env, r.key_sealed)), list: r.list_id } } catch { return null } }
const brevo = (key, path, init = {}) => fetch(BREVO + path, { ...init, headers: { 'api-key': key, accept: 'application/json', 'content-type': 'application/json' } });
const MD = s => { const m = /^(?:\d{4}-)?(\d{2})-(\d{2})$/.exec(String(s || '')); return m ? m[1] + '-' + m[2] : '' };
const prefsOf = r => { const d = { news: 1, birthday: 1, anniversary: 1 }; try { return { ...d, ...JSON.parse(r.prefs || '{}') } } catch { return d } };
