  let b = []; try { b = (await env.LEADS.prepare('SELECT id,created_at,name,email,phone,prefs,unsub_at FROM cove_signups WHERE COALESCE(spam,0)=0 AND brand=?').bind(brand).all()).results.map(r => ({ ...r, src: 'signup' })) } catch { }
