// Social links (v20): features.social = { links:{facebook,instagram,tiktok,x,youtube,yelp,google}, google_loc:{<locSlug>:url} }
const SOCIAL_NETS = { facebook: ['facebook.com', 'fb.com'], instagram: ['instagram.com'], tiktok: ['tiktok.com'], x: ['x.com', 'twitter.com'], youtube: ['youtube.com', 'youtu.be'], linkedin: ['linkedin.com'], yelp: ['yelp.com'], google: ['google.com', 'g.page', 'goo.gl', 'maps.app.goo.gl'] };
