const AI_POST_RULES = `Write ONE social media post. Rules (Loaded Nacho content standard):
- More than one sentence (two to four short sentences).
- Aim at awareness, sales and bringing in new customers; end with a clear call to action.
- Mention the location by name when one is given.
- Include the website link exactly as given on its own at the end.
- Use only facts from the FACTS and NOTES. Never invent prices, dates, deals or menu items.
- Friendly brand voice, up to two fitting emojis, up to three hashtags. Plain text only. No quotes around the post.
- Output ONLY the post text, with the website link as the very last line. Never copy FACTS lines (like "Hours: ..." or "Catering: ...") into the post.`;
// AIFIX1: help-tab hint + post cleanup
const MS_HELP_MAP = [[/holiday|hours?|closed|open(ing)?\b|special/i, 'Hours & specials'], [/menu|item|dish|price|photo|option/i, 'Menu'], [/reserv|table|booking/i, 'Reservations'], [/cater/i, 'Catering'], [/job|hiring|applica|careers?/i, 'Applications'], [/blog|article/i, 'Blog posts'], [/loyal|club|birthday|newsletter|email (members|list)/i, 'Loyalty'], [/social|post|facebook|instagram|tiktok|review|comment/i, 'Social'], [/contact form|messages?/i, 'Messages'], [/chat|assistant|custom answer/i, 'Chats'], [/analytic|traffic|visits?/i, 'Site Analytics'], [/team|invite|user|role|permission|alert recipient/i, 'Team'], [/setting|module|footer|business profile/i, 'Settings'], [/password|passkey|two-step|2fa|notification/i, 'Account menu']];
function aiHelpHint(q) { const t = []; for (const [re, tab] of MS_HELP_MAP) if (re.test(q) && !t.includes(tab)) t.push(tab); return t.slice(0, 2) }
const AI_FACTLINE = /^\s*(hours|catering|reservations|website|business|locations?|phone|address|menu|facts|notes|location)\s*:/i;
const AI_BARE_TLD = 'com|net|org|io|co|us|app|biz|info|me|uk|ca|restaurant|pizza|bar|cafe|food';
const AI_HOURS_SENT = /[^.!?\n]*?(?:hours of operation|hours are|we(?:'re| are) open)\s*:?[^.!?\n]*?\d{1,2}(?::\d{2})?\s*(?:am|pm)[^.!?\n]*[.!?]?/gi;
const AI_POST_CTA = /\b(book|reserv|order|call|buy|sign up|don'?t miss|come (?:in|down)|join us|try it)\b/i;
const AI_POST_BRAND = /\b(best|delicious|award|famous|perfect|proud|favorite|mouth-?watering|sizzling|unforgettable|expert|affordable)\b/i;
function aiPlainSite(site) { const s = String(site || '').trim().replace(/\/+$/, ''); if (!s) return null; return { s, re: new RegExp(s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '(?=$|\\s|[^/?#\\w])', 'i') } }
function aiBareDomains(text, fixes) { const re = new RegExp('(^|[^A-Za-z0-9@:/])((?:[a-z0-9-]+\\.)+(?:' + AI_BARE_TLD + '))\\b', 'gi'); let n = 0;
  const out = text.replace(re, (m, pre, host, offset, str) => { if (/https?:\/\//i.test(str.slice(Math.max(0, offset - 8), offset + pre.length))) return m; n++; return pre + 'https://' + host });
  if (n) fixes.push('added https to bare domain'); return out }
function aiStripHoursRestate(text, fixes) { const re = new RegExp(AI_HOURS_SENT.source, 'gi'); let out = '', last = 0, cut = false;
  for (const m of text.matchAll(re)) { const piece = m[0]; if (AI_POST_CTA.test(text.slice(0, m.index)) && !AI_POST_CTA.test(piece) && !AI_POST_BRAND.test(piece)) { out += text.slice(last, m.index); last = m.index + piece.length; cut = true } }
  out += text.slice(last); if (cut) fixes.push('removed hours restatement'); return out.replace(/[ \t]{2,}/g, ' ').replace(/[ \t]+\n/g, '\n') }
function aiPostClean(t, site) { const fixes = [], plain = aiPlainSite(site);
  let text = aiStripHoursRestate(aiBareDomains(String(t), fixes), fixes); let lines = text.split('\n');
  if (plain) { const i = lines.findIndex(l => plain.re.test(l)); if (i >= 0 && i < lines.length - 1 && lines.slice(i + 1).some(l => l.trim())) { lines = lines.slice(0, i + 1); fixes.push('cut text after link') } }
  const n = lines.length; lines = lines.filter(l => !AI_FACTLINE.test(l)); if (lines.length < n) fixes.push('removed fact-sheet lines');
  let out = lines.join('\n').replace(/\n{3,}/g, '\n\n').trim();
  if (plain && out.split('\n').pop().trim().toLowerCase() !== plain.s.toLowerCase()) {
    const trail = new RegExp('(^|\\s)' + plain.s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '\\s*$', 'i');
    if (trail.test(out)) { out = out.replace(trail, '\n' + plain.s).replace(/\n{3,}/g, '\n\n').trim(); fixes.push('moved website link to its own line') }
    else { out = (out ? out + '\n' : '') + plain.s; fixes.push('added website link') }
  }
  if (plain) { const kept = out.split('\n'); while (kept.length >= 2 && kept[kept.length - 1].trim().toLowerCase() === plain.s.toLowerCase() && kept[kept.length - 2].trim().toLowerCase() === plain.s.toLowerCase()) kept.pop(); out = kept.join('\n').trim() }
  return { t: out, fixes } }
