function msGuidePick(q, n = 4) { const w = String(q).toLowerCase().match(/[a-z0-9&]{3,}/g) || []; return MS_GUIDE.map(s => { const hay = (s.title + ' ' + s.kw).toLowerCase(), body = s.text.toLowerCase(); let sc = 0; for (const t of w) { if (hay.includes(t)) sc += 3; else if (body.includes(t)) sc += 1; else if (t.length >= 5 && hay.includes(t.slice(0, -1))) sc += 2 } return { s, sc } }).filter(x => x.sc > 0).sort((a, b) => b.sc - a.sc).slice(0, n).map(x => x.s) }
function msGuideBest(q) { const w = (String(q).toLowerCase().match(/[a-z0-9&]{3,}/g) || []).filter(t => !['how','the','and','for','add','can','you','what','with','mother','sauce','change','set'].includes(t)); let best = null, bs = 0; for (const s of MS_GUIDE) { const hay = (s.title + ' ' + s.kw).toLowerCase(); let sc = 0; for (const t of w) if (hay.includes(t)) sc += 3; if (sc > bs) { bs = sc; best = s } } return bs >= 6 ? best : null }

const AI_ASK_SYS = (name, guide, kb) => `You are Remy, the Mother Sauce assistant for ${name}, talking with someone who runs or works at this business. Mother Sauce is the web app they use to manage their restaurant website.
Rules:
- General questions (marketing, menu or promo ideas, review reply wording, social post ideas, general knowledge): answer normally, helpfully and briefly. When the idea is about this business, use the BUSINESS FACTS; never state prices, hours, dates or policies that are not in them.
- Questions about how to do something in Mother Sauce: use ONLY the GUIDE below. Name only pages, tabs and buttons written in the GUIDE, using the steps given. Never invent buttons, menus, sections or settings.
- If a Mother Sauce question is not covered by the GUIDE, reply with exactly: NOT_IN_GUIDE
- The email tool is called the Mail Service. Never name any other email or social software vendor.
- Plain text, short paragraphs or numbered steps, no markdown headings.
GUIDE:
${guide}
BUSINESS FACTS:
${kb}`;
const AI_ASK_NOPE = 'That isn’t covered in the Mother Sauce guide, so I don’t want to guess. You can ask Loaded Nacho from Support (New ticket).';
function aiAskClean(t) { t = String(t || '').replace(/metricool/gi, 'Mail Service').trim(); if (/NOT_IN_GUIDE|^UNSURE\b/.test(t) || !t) return { answer: AI_ASK_NOPE, handoff: true }; return { answer: t.slice(0, 2000), handoff: false } }
