/* OpenRouter's /activity report only lists FINISHED days, so "today" is always empty and the week lags. Its /credits total is live, so we save
   that all-time spend once per UTC day (portal_api_snap) and measure use as the difference. Week = now minus the saved total from 7+ days ago.
   Until a week of history exists the week is approximate: finished days from /activity plus the live difference since yesterday's last view. */
async function orSnap(env, totalNow, finishedWeek) {
  await env.DB.prepare('CREATE TABLE IF NOT EXISTS portal_api_snap(day TEXT NOT NULL,provider TEXT NOT NULL,open_total REAL NOT NULL,total REAL NOT NULL,updated_at INTEGER,PRIMARY KEY(day,provider))').run();
  const dayOf = off => new Date(Date.now() - off * 864e5).toISOString().slice(0, 10), td = dayOf(0), yd = dayOf(1), week0 = dayOf(7), floor = dayOf(9);
  const rows = ((await env.DB.prepare("SELECT day,open_total,total FROM portal_api_snap WHERE provider='openrouter' AND day<=? ORDER BY day DESC LIMIT 14").bind(td).all()).results) || [];
  const todayRow = rows.find(r => r.day === td), yRow = rows.find(r => r.day === yd), old = rows.find(r => r.day <= week0 && r.day >= floor);
  const base = yRow ? yRow.total : todayRow ? todayRow.open_total : totalNow, today = Math.max(0, totalNow - base);
  const week = old ? Math.max(0, totalNow - old.total) : Math.max(0, finishedWeek) + today;
  await env.DB.prepare("INSERT INTO portal_api_snap(day,provider,open_total,total,updated_at) VALUES(?,'openrouter',?,?,?) ON CONFLICT(day,provider) DO UPDATE SET total=excluded.total,updated_at=excluded.updated_at").bind(td, totalNow, totalNow, Date.now()).run();
  await env.DB.prepare('DELETE FROM portal_api_snap WHERE day<?').bind(dayOf(45)).run();
  return { week: Math.round(week * 100) / 100, today: Math.round(today * 100) / 100, approx: !old };
}
