    return J({ unread: rows.length, awaiting: awOut, sections, by, items: rows.slice(0, 50).map(r => ({ ...tk[r.id], id: r.id, type: r.type, label: actLabel(r.type), section: r.section, ref: r.ref_id, client: r.client_slug, client_name: cn[r.client_slug] || r.client_slug, location: r.location_slug, location_name: r.location_slug === '*' ? '' : ln[r.client_slug + '/' + r.location_slug] || r.location_slug, summary: r.summary, at: r.created_at, sound: !!r.__sound })) }, 200, { 'cache-control': 'no-store' });
