      for (const s of slugs) { if (u.role !== 'agency' && !slugsOf(u).includes(s)) continue; const mx = (await env.DB.prepare('SELECT COALESCE(MAX(id),0) m FROM portal_activity WHERE client_slug=?').bind(s).first()).m;
        await env.DB.prepare('INSERT INTO portal_activity_clear(email,client_slug,cleared_id) VALUES(?,?,?) ON CONFLICT(email,client_slug) DO UPDATE SET cleared_id=MAX(cleared_id,excluded.cleared_id)').bind(u.email, s, mx).run() }
