    let ids = (Array.isArray(b.ids) ? b.ids : []).map(Number).filter(Boolean).slice(0, 200);
    if (b.type && b.ref != null) ids = ids.concat((await env.DB.prepare('SELECT id FROM portal_activity WHERE client_slug=? AND type=? AND ref_id=?').bind(String(b.client || ''), String(b.type), String(b.ref)).all()).results.map(r => r.id));
    if (b.section && b.client) ids = ids.concat((await activityUnread(env, u, String(b.client))).filter(r => r.section === b.section).map(r => r.id));
    for (const id of ids) { const r = await env.DB.prepare('SELECT * FROM portal_activity WHERE id=?').bind(id).first(); if (r && actVisible(u, r)) await env.DB.prepare('INSERT OR IGNORE INTO portal_activity_reads(email,activity_id,read_at) VALUES(?,?,?)').bind(u.email, id, now).run() }
    return J({ ok: true, marked: ids.length });
