  if (!t) return { dup: true };
  await env.DB.prepare("INSERT INTO portal_ticket_msgs(ticket_id,author,author_role,body,internal,created_at) VALUES(?,?,'client',?,0,?)").bind(t.id, cl(r.email) || 'website', String(r.message || '').slice(0, 10000) || '(no message)', at).run();
