    const to = slug === '_ln' ? String(env.LN_CONTACT_TO || 'hello@loadednacho.com').split(',') : await recipientsFor(env, slug, 'contact', r.location || '');
    const cn = slug === '_ln' ? 'Loaded Nacho' : (await env.DB.prepare('SELECT name FROM portal_clients WHERE slug=?').bind(slug).first() || {}).name;
