// ---- Website address helpers (v30 draft) ----
function normalizeSite(raw) {
  let s = String(raw || '').trim().replace(/\s+/g, ''); if (!s || s.length > 300) return null;
  if (!/^[a-z][a-z0-9+.-]*:\/\//i.test(s)) s = 'https://' + s.replace(/^\/+/, '');
  let x; try { x = new URL(s) } catch { return null }
  if (!/^https?:$/.test(x.protocol) || x.username || x.password || x.port && !/^(80|443)$/.test(x.port)) return null;
  const h = x.hostname.toLowerCase(); if (!/^[a-z0-9-]+(\.[a-z0-9-]+)*\.[a-z]{2,}$/.test(h) || /^\d+\.\d+\.\d+\.\d+$/.test(h)) return null;
  const path = x.pathname === '/' ? '' : x.pathname.replace(/\/+$/, '');
  return x.protocol + '//' + h + path + x.search;
}
// v32: read-only domain status through DNS-over-HTTPS (Cloudflare 1.1.1.1 JSON API). No DNS or zone writes anywhere.
async function dnsStatus(site) {
  const n = normalizeSite(site); if (!n) return { ok: false, reason: 'No website address is set.' };
  const host = new URL(n).hostname, apex = host.replace(/^www\./, '');
  const q = async (name, type) => { try { const r = await fetch(`https://cloudflare-dns.com/dns-query?name=${encodeURIComponent(name)}&type=${type}`, { headers: { accept: 'application/dns-json' }, signal: AbortSignal.timeout(5000) }); const j = await r.json(); return (j.Answer || []).filter(a => a.type === { A: 1, AAAA: 28, MX: 15 }[type]).map(a => a.data) } catch { return null } };
  const [a, aaaa, mx] = await Promise.all([q(host, 'A'), q(host, 'AAAA'), q(apex, 'MX')]);
  const web = await checkSite(n);
  return { ok: true, host, resolves: !!((a && a.length) || (aaaa && aaaa.length)), addresses: [...(a || []), ...(aaaa || [])].slice(0, 4), https: !!(web.ok && web.https), status: web.status || null, mx: (mx || []).map(x => x.replace(/^\d+\s+/, '').replace(/\.$/, '')).slice(0, 4), dnsError: a === null && mx === null };
}
async function checkSite(site) {
  const n = normalizeSite(site); if (!n) return { ok: false, reason: 'No website address is set.' };
  const t0 = Date.now();
  try {
    const r = await fetch(n, { method: 'GET', redirect: 'follow', headers: { 'user-agent': 'LoadedNacho-SiteCheck/1.0' }, signal: AbortSignal.timeout(8000) });
    const fin = r.url || n; return { ok: r.status < 400, status: r.status, https: fin.startsWith('https://'), url: n, finalUrl: fin, redirected: fin.replace(/\/$/, '') !== n.replace(/\/$/, ''), ms: Date.now() - t0 };
  } catch (e) { return { ok: false, url: n, https: n.startsWith('https://'), reason: /timeout|abort/i.test(e.name + e.message) ? 'No answer within 8 seconds.' : 'Could not reach the site.' } }
}


