function routeNeed(p, m) {
  let mm = p.match(/^\/api\/analytics\/([a-z0-9_-]+)$/); if (mm && mm[1] !== '_ln') return [mm[1], 'analytics', 'view'];
  mm = p.match(/^\/api\/client\/([a-z0-9-]+)(?:\/([a-z]+))?/); if (!mm) return null;
  const w = m === 'GET' ? 'view' : 'edit';
  if (mm[2] === 'spam') { const s = SPAM_MODS[p.split('/')[5]]; return s ? [mm[1], s.sec, w] : [mm[1], '__deny', 'edit'] } // v35 spam
  if (mm[2] === 'reservations' && /\/email$/.test(p)) return [mm[1], 'reservations', 'view']; // same people who can open the card; status changes stay edit
  if (mm[2] === 'logo' && m === 'GET') return null; // brand image is not a secret; logoRoutes allows any canSee caller. Writes stay settings edit.
  if (mm[2] === 'tablet') return /\/(pin|code|release)$/.test(p) ? [mm[1], '__any', 'view'] : [mm[1], 'settings', m === 'GET' ? 'view' : 'edit']; // PIN and emailed code need a live session only; the settings card is Owner/Admin
  const sec = { jobs: 'applications', security: 'team', reservations: 'reservations', applications: 'applications', catering: 'catering', messages: 'home', recipients: 'notifications', team: 'team', audit: 'team', features: 'settings', website: 'settings', locations: 'hours', loyalty: 'loyalty', blog: 'blog', menuphoto: 'menu', forms: 'settings', resvrules: 'reservations', contact: 'settings', readiness: 'home', catmenus: 'catering', social: 'social', logo: 'settings' }[mm[2] || ''];
  if (!mm[2]) return m === 'GET' ? [mm[1], '__any', 'view'] : null; // t887u: the business record (name/features) is needed to boot for any role with at least one section, e.g. social-only // PUT checks menu/hours by body below
  return sec ? [mm[1], sec, w] : [mm[1], '__deny', 'edit'];
}
