    const em = mem.map(x => x.email); if (!em.length) return J({ members: [], summary: { total: 0, twoStep: 0, passkey: 0, noPassword: 0, failed24h: 0 }, primary: cl.primary_owner_email || null });
    const q = em.map(() => '?').join(',');
    const last = Object.fromEntries((await env.DB.prepare(`SELECT email,MAX(at) at FROM portal_signins WHERE ok=1 AND email IN (${q}) GROUP BY email`).bind(...em).all()).results.map(r => [r.email, r.at]));
    const fails = Object.fromEntries((await env.DB.prepare(`SELECT email,COUNT(*) n FROM portal_signins WHERE ok=0 AND at>? AND email IN (${q}) GROUP BY email`).bind(now - 864e5, ...em).all()).results.map(r => [r.email, r.n]));
    const sess = Object.fromEntries((await env.DB.prepare(`SELECT email,COUNT(*) n FROM portal_sessions WHERE expires_at>? AND email IN (${q}) GROUP BY email`).bind(now, ...em).all()).results.map(r => [r.email, r.n]));
