    const act = rows.filter(r => r.active);
    return J({ members: rows, primary: cl.primary_owner_email || null, me: u.email, summary: { total: act.length, twoStep: act.filter(r => r.totp || r.mfa_email || r.passkeys).length, passkey: act.filter(r => r.passkeys).length, noPassword: act.filter(r => !r.has_pw).length, failed24h: act.reduce((a, r) => a + r.failed24h, 0) } });
