    if (!sameOrigin(req)) return J({ error: 'bad origin' }, 403);
    const tgt = decodeURIComponent(mm[2]).toLowerCase(), x = mem.find(r => r.email === tgt); if (!x) return J({ error: 'nf' }, 404);
