    if (p === '/embed/support.js' && (m === 'GET' || m === 'HEAD')) return new Response(m === 'HEAD' ? null : PUBSUP_EMBED, { headers: { 'content-type': 'text/javascript; charset=utf-8', 'cache-control': 'public, max-age=300', 'access-control-allow-origin': '*', 'cross-origin-resource-policy': 'cross-origin', 'x-content-type-options': 'nosniff' } });
