function demoLanding(why) {
  const msg = { idle: 'Your demo started fresh after 30 quiet minutes. Jump back in anytime.', out: 'Your demo started fresh. Jump back in anytime.', rate: 'Too many demos from this network. Please try again in an hour.', busy: 'The demo is busy right now. Please try again in a few minutes.', err: 'Something went wrong starting the demo. Please try again.' }[why] || '';
  return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Try Mother Sauce · Demo</title><meta name="robots" content="noindex"><meta name="color-scheme" content="light dark"><style>
:root{--bg:#faf6ef;--card:#fff;--ink:#1a1410;--mute:#6b6058;--line:#eadfce;--gold:#f7892b}@media(prefers-color-scheme:dark){:root{--bg:#120d14;--card:#1c1520;--ink:#f3ece4;--mute:#b3a79c;--line:#2f2533}}
*{box-sizing:border-box}body{margin:0;min-height:100vh;display:grid;place-items:center;background:var(--bg);color:var(--ink);font-family:system-ui,-apple-system,Segoe UI,Roboto,sans-serif;padding:24px}
.c{background:var(--card);border:1px solid var(--line);border-radius:20px;max-width:520px;width:100%;padding:36px 32px;box-shadow:0 10px 40px #0000000f}h1{margin:0 0 6px;font-size:28px}.k{color:var(--gold);font-weight:800;letter-spacing:.08em;font-size:12px;text-transform:uppercase}
p{color:var(--mute);line-height:1.55;margin:10px 0}ul{color:var(--mute);line-height:1.7;padding-left:20px;margin:14px 0 22px}button{width:100%;border:0;border-radius:999px;background:var(--gold);color:#1a0f08;font-weight:800;font-size:16px;padding:14px 20px;cursor:pointer}button:hover{filter:brightness(1.05)}
.brand{display:flex;gap:10px;align-items:center;font-weight:800;font-size:20px;margin:0 0 20px}.brand img{width:36px;height:36px}.brand b{color:var(--gold)}.brand span{line-height:1.05}.brand small{display:block;font-size:10px;letter-spacing:.14em;text-transform:uppercase;color:var(--mute);font-weight:700;margin-top:3px}h1{margin-top:0}.n{background:#f7892b1f;border:1px solid #f7892b55;color:var(--ink);border-radius:12px;padding:10px 14px;font-size:14px;margin:0 0 16px}.s{font-size:12.5px;text-align:center;margin-top:14px}#dmb{position:relative;overflow:hidden;display:inline-flex;align-items:center;justify-content:center;gap:10px}#dmb .sp{display:none;width:16px;height:16px;border-radius:50%;border:2px solid currentColor;border-right-color:transparent;animation:dmspin .7s linear infinite}#dmb.ld .sp{display:inline-block}#dmb.ld{cursor:progress;opacity:.92}#dmb.ld::after{content:"";position:absolute;inset:0;background:linear-gradient(100deg,transparent 30%,rgba(255,255,255,.28) 50%,transparent 70%);background-size:200% 100%;animation:dmsh 1.2s ease-in-out infinite}@keyframes dmspin{to{transform:rotate(360deg)}}@keyframes dmsh{from{background-position:150% 0}to{background-position:-50% 0}}@media(prefers-reduced-motion:reduce){#dmb .sp{animation-duration:1.6s}#dmb.ld::after{animation:none}}</style></head><body><main class="c">
<div class="brand"><img src="/a/mark-2x.png" alt=""><span>Loaded <b>Nacho</b><small class="mf">Mother Sauce</small></span></div><h1>Take Mother Sauce for a spin</h1>
${msg ? `<div class="n" role="status">${msg}</div>` : ''}<p>Explore a sample restaurant with everything set up: menu, reservations, catering, hiring, loyalty, reviews and more. Click around and try anything.</p>
<ul><li>Your changes are just for you.</li><li>Nothing gets sent to anyone.</li><li>It all starts fresh when you leave.</li></ul>
<form method="post" action="/demo/start" id="dmf"><button type="submit" id="dmb"><span class="sp" aria-hidden="true"></span><span class="lb">Start the demo</span></button></form><script>(function(){var f=document.getElementById('dmf'),b=document.getElementById('dmb');f.addEventListener('submit',function(e){if(b.disabled){e.preventDefault();return}setTimeout(function(){b.disabled=true},0);b.classList.add('ld');b.setAttribute('aria-busy','true');b.querySelector('.lb').textContent='Setting up your kitchen\u2026'});addEventListener('pageshow',function(){b.disabled=false;b.classList.remove('ld');b.removeAttribute('aria-busy');b.querySelector('.lb').textContent='Start the demo'})})()</script><p class="s">No sign-up needed. All names and data are made up.</p></main></body></html>`;
}
